"""Exact greedy head: discard rows only using conservative Cauchy bounds."""
import mlx.core as mx

PARTIAL=r'''
uint tid=thread_position_in_threadgroup.x;
uint lane=tid%32, warp=tid/32;
uint row=threadgroup_position_in_grid.x*32+warp;
float a[4]={0,0,0,0};
for(uint i=lane;i<PREFIX;i+=32) {
    float z=float(x[i]);
    for(uint j=0;j<4;j++)a[j]+=z*float(w[(row+j*8)*K+i]);
}
for(uint j=0;j<4;j++) {
    float z=simd_sum(a[j]);
    if(lane==0)p[row+j*8]=z;
}
'''
TAIL=r'''
uint tid=thread_position_in_threadgroup.x;
uint lane=tid%32, warp=tid/32;
uint row=threadgroup_position_in_grid.x*32+warp;
bool active[4];
float a[4]={0,0,0,0};
bool any=false;
for(uint j=0;j<4;j++) {
    uint r=row+j*8;
    float tail=rn[r]*xn[1];
    // Ample guard for FP32 summation/norm errors, plus two BF16 ulps of
    // slack when comparing with the seed candidate's rounded score.
    float err=0.001f*(pn[r]*xn[0]+tail)+0.0001f;
    T upper=T(p[r]+tail+err);
    float threshold_safe=float(threshold)-metal::abs(float(threshold))*0.0079f-0.001f;
    active[j]=float(upper)>=threshold_safe;
    any=any||active[j];
    if(lane==0)out[r]=T(-INFINITY);
}
if(!any)return;
for(uint i=PREFIX+lane;i<K;i+=32) {
    float z=float(x[i]);
    for(uint j=0;j<4;j++)if(active[j])a[j]+=z*float(w[(row+j*8)*K+i]);
}
for(uint j=0;j<4;j++) {
    float z=simd_sum(a[j]);
    if(lane==0 && active[j])out[row+j*8]=T(p[row+j*8]+z);
}
'''
partial_kernel=mx.fast.metal_kernel(name='head_partial',input_names=['x','w'],output_names=['p'],source=PARTIAL)
tail_kernel=mx.fast.metal_kernel(name='head_tail',input_names=['x','w','p','pn','rn','xn','threshold'],output_names=['out'],source=TAIL)

class BoundedHead:
    def __init__(self,w,prefix=512):
        self.w=w;self.prefix=prefix
        wf=w.astype(mx.float32)
        self.pn=mx.sqrt(mx.sum(wf[:,:prefix]**2,axis=-1))
        self.rn=mx.sqrt(mx.sum(wf[:,prefix:]**2,axis=-1))
        mx.eval(self.pn,self.rn)

    def scores(self,h):
        n,k=self.w.shape
        template=[('T',h.dtype),('K',k),('PREFIX',self.prefix)]
        p=partial_kernel(inputs=[h,self.w],template=template,grid=((n//32)*256,1,1),threadgroup=(256,1,1),
                         output_shapes=[(n,)],output_dtypes=[mx.float32])[0]
        pick=mx.argmax(p)
        row=mx.take(self.w,pick.reshape(1),axis=0)
        threshold=(h@row.T).reshape(())
        x=h.reshape(-1).astype(mx.float32)
        xn=mx.stack([mx.sqrt(mx.sum(x[:self.prefix]**2)),mx.sqrt(mx.sum(x[self.prefix:]**2))])
        out=tail_kernel(inputs=[h,self.w,p,self.pn,self.rn,xn,threshold],template=template,
                        grid=((n//32)*256,1,1),threadgroup=(256,1,1),output_shapes=[(n,)],output_dtypes=[h.dtype])[0]
        return out,p,xn,threshold

    def __call__(self,h):
        return mx.argmax(self.scores(h)[0])

